const [error, setError] = useState(null);
const [savedArticles, setSavedArticles] = useState([]);
const [expandedArticles, setExpandedArticles] = useState({});
const [isAdmin, setIsAdmin] = useState(false);

const token = localStorage.getItem("token");
const currentUserId = localStorage.getItem("user_id");
const navigate = useNavigate();

// Завантаження каналів
useEffect(() => {
const fetchChannels = async () => {
try {
const res = await fetch("[http://127.0.0.1:8000/api/channels/](http://127.0.0.1:8000/api/channels/)", {
headers: {
"Content-Type": "application/json",
...(token && { Authorization: `Bearer ${token}` }),
},
});


    if (!res.ok) throw new Error("Помилка завантаження каналів");
    const data = await res.json();
    setChannels(Array.isArray(data) ? data : data.results || []);
  } catch (err) {
    console.error(err);
    setError("Не вдалося завантажити канали");
  }
};
fetchChannels();


}, [token]);

// Відкрити статті каналу
const openChannel = async (channelId) => {
setSelectedChannel(channelId);
try {
const res = await fetch(
`http://127.0.0.1:8000/api/channels/${channelId}/articles/`,
{
headers: {
"Content-Type": "application/json",
...(token && { Authorization: `Bearer ${token}` }),
},
}
);
if (!res.ok) throw new Error("Не вдалося завантажити статті каналу");
const data = await res.json();
setArticles(Array.isArray(data) ? data : data.results || []);
} catch (err) {
console.error(err);
setError(err.message);
setArticles([]);
}
};

// Підписка / Відписка
const toggleSubscription = async (channelId, isSubscribed) => {
try {
const url = `http://127.0.0.1:8000/api/channels/${channelId}/${
        isSubscribed ? "unsubscribe" : "subscribe"
      }/`;
const res = await fetch(url, {
method: "POST",
headers: {
"Content-Type": "application/json",
...(token && { Authorization: `Bearer ${token}` }),
},
});


  if (!res.ok) throw new Error("Помилка підписки");
  setChannels((prev) =>
    prev.map((ch) =>
      ch.id === channelId ? { ...ch, is_subscribed: !isSubscribed } : ch
    )
  );
} catch (err) {
  console.error(err);
  setError(err.message);
}


};

// Зберегти статтю
const toggleSave = (id) => {
setSavedArticles((prev) =>
prev.includes(id) ? prev.filter((sid) => sid !== id) : [...prev, id]
);
};

// Коментарі
const toggleComments = (id) => {
setExpandedArticles((prev) => ({ ...prev, [id]: !prev[id] }));
};

// Видалити статтю
const handleDelete = async (id) => {
try {
const res = await fetch(`http://127.0.0.1:8000/api/articles/${id}/`, {
method: "DELETE",
headers: {
"Content-Type": "application/json",
...(token && { Authorization: `Bearer ${token}` }),
},
});
if (!res.ok) throw new Error("Не вдалося видалити статтю");
setArticles((prev) => prev.filter((a) => a.id !== id));
} catch (err) {
console.error(err);
setError(err.message);
}
};

// === ІНТЕРФЕЙС ===
return ( <div className="subscriptions-container"> <h2>Підписки</h2>
{error && <p className="error">{error}</p>}


  {!selectedChannel ? (
    <>
      {channels.length === 0 ? (
        <p>Поки немає каналів</p>
      ) : (
        <ul className="channel-list">
          {channels.map((ch) => (
            <li key={ch.id} className="channel-item">
              <span
                className="channel-name"
                onClick={() => openChannel(ch.id)}
              >
                {ch.name || "Без назви"}
              </span>
              <button
                className={`subscribe-btn ${
                  ch.is_subscribed ? "unsubscribe" : "subscribe"
                }`}
                onClick={() => toggleSubscription(ch.id, ch.is_subscribed)}
              >
                {ch.is_subscribed ? "Відписатись" : "Підписатись"}
              </button>
            </li>
          ))}
        </ul>
      )}
    </>
  ) : (
    <div className="articles-container">
      <button className="back-btn" onClick={() => setSelectedChannel(null)}>
        ← Назад до каналів
      </button>
      <h2>Статті каналу</h2>

      {articles.length === 0 ? (
        <p>У цього каналу поки немає статей.</p>
      ) : (
        <div className="articles-grid">
          {articles.map((a) => (
            <div key={a.id} className="article-card">
              {a.image && (
                <img
                  src={
                    a.image.startsWith("http")
                      ? a.image
                      : `http://127.0.0.1:8000${a.image}`
                  }
                  alt={a.title}
                  className="article-image"
                />
              )}
              <h3>{a.title || "(Без назви)"}</h3>
              <p>
                {a.excerpt ||
                  (a.content?.substring(0, 120) + "...") ||
                  "(Без опису)"}
              </p>
              <small>
                {a.category} |{" "}
                {a.created_at
                  ? new Date(a.created_at).toLocaleDateString("uk-UA")
                  : ""}
              </small>

              <button
                onClick={() => toggleSave(a.id)}
                className={`save-btn ${
                  savedArticles.includes(a.id) ? "saved" : ""
                }`}
              >
                {savedArticles.includes(a.id)
                  ? "💾 Збережено"
                  : "📥 Зберегти"}
              </button>

              {isAdmin && (
                <div className="admin-controls">
                  <button onClick={() => navigate(`/edit-article/${a.id}`)}>
                    ✏️ Редагувати
                  </button>
                  <button onClick={() => handleDelete(a.id)}>
                    🗑️ Видалити
                  </button>
                </div>
              )}

              <button onClick={() => toggleComments(a.id)}>
                💬{" "}
                {expandedArticles[a.id]
                  ? "Сховати коментарі"
                  : "Показати коментарі"}
              </button>

              {expandedArticles[a.id] && (
                <CommentsSection
                  articleId={a.id}
                  token={token}
                  currentUserId={currentUserId}
                  isAdmin={isAdmin}
                />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )}
</div>


);
}

export default Subscriptions;
